/// cos(2^-1200) = 1 - 2^-2401 < 1: AUDITED correct (depth-hint driver),
/// left unchanged. Directed-down gives pred(1); nearest/up give 1.
#[test]
fn cos_deep_audited() {
    let x = BigFloat::try_from_i64_exact(1, 53)
        .unwrap()
        .scale_by_pow2(-1200)
        .0;
    let one = BigFloat::try_from_i64_exact(1, 53).unwrap();
    let pred1 = one
        .sub(&one.scale_by_pow2(-53).0, RoundingMode::NearestEven)
        .0;
    assert_eq!(
        x.cos_round(53, RoundingMode::NearestEven)
            .unwrap()
            .0
            .total_cmp(&one),
        Ordering::Equal
    );
    assert_eq!(
        x.cos_round(53, RoundingMode::TowardZero)
            .unwrap()
            .0
            .total_cmp(&pred1),
        Ordering::Equal
    );
    assert_eq!(
        x.cos_round(53, RoundingMode::TowardNegative)
            .unwrap()
            .0
            .total_cmp(&pred1),
        Ordering::Equal
    );
    assert_eq!(
        x.cos_round(53, RoundingMode::TowardPositive)
            .unwrap()
            .0
            .total_cmp(&one),
        Ordering::Equal
    );
}

/// sec(2^-1200) = 1/cos = 1 + 2^-2401 > 1: AUDITED correct (depth-hint
/// driver), left unchanged. Nearest/down give 1; up gives succ(1).
#[test]
fn sec_deep_audited() {
    let x = BigFloat::try_from_i64_exact(1, 53)
        .unwrap()
        .scale_by_pow2(-1200)
        .0;
    let one = BigFloat::try_from_i64_exact(1, 53).unwrap();
    let succ1 = one
        .add(&one.scale_by_pow2(-52).0, RoundingMode::NearestEven)
        .0;
    assert_eq!(
        x.sec_round(53, RoundingMode::NearestEven)
            .unwrap()
            .0
            .total_cmp(&one),
        Ordering::Equal
    );
    assert_eq!(
        x.sec_round(53, RoundingMode::TowardZero)
            .unwrap()
            .0
            .total_cmp(&one),
        Ordering::Equal
    );
    assert_eq!(
        x.sec_round(53, RoundingMode::TowardPositive)
            .unwrap()
            .0
            .total_cmp(&succ1),
        Ordering::Equal
    );
}
